const REQUIRED_FIELDS = ['id', 'routePath', 'viewFile', 'title']

if (import.meta.env.DEV) {
  const seenIds = new Set()
  const seenPaths = new Set()
  for (const item of REPORT_CATALOG) {
    for (const f of REQUIRED_FIELDS) {
      if (!item[f]) console.error(`[REPORT_CATALOG] 缺少必填字段 ${f}:`, item)
    }
    if (seenIds.has(item.id)) console.error(`[REPORT_CATALOG] id 重复: ${item.id}`)
    if (seenPaths.has(item.routePath)) console.error(`[REPORT_CATALOG] routePath 重复: ${item.routePath}`)
    seenIds.add(item.id)
    seenPaths.add(item.routePath)
  }
}

